test('Worker Passkey失败complete并发预占限制昂贵凭据查询为十次',async()=>{const e=env(),ip='198.51.100.77',payloads=[];for(let i=0;i<11;i++){const r=await call(e,'/api/passkeys/authentication/options',{method:'POST',body:{},headers:{'CF-Connecting-IP':`203.0.113.${i+1}`}}),option=await r.json();payloads.push({challengeId:option.challengeId,response:{id:'invalid_credential'}})}let reads=0;e.DB.onPasskeyRead=()=>{reads++};const responses=await Promise.all(payloads.map(body=>call(e,'/api/passkeys/authentication/complete',{method:'POST',body,headers:{'CF-Connecting-IP':ip}})));assert.deepEqual(responses.map(x=>x.status).sort(),[...Array(10).fill(400),429]);assert.equal(reads,10);assert.equal(e.DB.attempts.filter(x=>x.key===`passkey:${ip}`).length,10)});

