test('真实 Miniflare D1 在额度降低后原子拒绝恢复大附件版本且两张表均不变',async()=>{const mf=new Miniflare({modules:true,compatibilityDate:'2026-07-11',d1Databases:['DB'],script:'export default {fetch(){return new Response("ok")}}'});try{const db=await mf.getD1Database('DB'),now=Date.now();await db.exec('CREATE TABLE attachments(user_id TEXT,id TEXT,metadata_iv TEXT,metadata_ciphertext TEXT,object_key TEXT,ciphertext_size INTEGER,updated_at INTEGER,revision INTEGER,PRIMARY KEY(user_id,id));CREATE TABLE attachment_versions(user_id TEXT,attachment_id TEXT,source_revision INTEGER,metadata_iv TEXT,metadata_ciphertext TEXT,object_key TEXT,ciphertext_size INTEGER,PRIMARY KEY(user_id,attachment_id,source_revision));CREATE TABLE user_quotas(user_id TEXT PRIMARY KEY,attachment_bytes_limit INTEGER,expires_at INTEGER);CREATE TABLE backup_import_locks(user_id TEXT PRIMARY KEY)');await db.batch([db.prepare('INSERT INTO attachments VALUES(?,?,?,?,?,?,?,?)').bind('u1','a1','small','small','small-key',16,now,2),db.prepare('INSERT INTO attachment_versions VALUES(?,?,?,?,?,?,?)').bind('u1','a1',1,'large','large','large-key',128),db.prepare('INSERT INTO user_quotas VALUES(?,?,NULL)').bind('u1',64)]);const result=await db.prepare('UPDATE attachments SET metadata_iv=?,metadata_ciphertext=?,object_key=?,ciphertext_size=?,updated_at=?,revision=revision+1 WHERE user_id=? AND id=? AND revision=? AND NOT EXISTS(SELECT 1 FROM backup_import_locks WHERE user_id=?) AND (SELECT COALESCE(SUM(ciphertext_size),0) FROM attachments WHERE user_id=?)-ciphertext_size+?<=COALESCE((SELECT attachment_bytes_limit FROM user_quotas WHERE user_id=? AND (expires_at IS NULL OR expires_at>?)),?) RETURNING revision').bind('large','large','large-key',128,now,'u1','a1',2,'u1','u1',128,'u1',now,209715200).all();assert.equal(result.results.length,0);const current=await db.prepare('SELECT object_key,ciphertext_size,revision FROM attachments WHERE user_id=? AND id=?').bind('u1','a1').first(),version=await db.prepare('SELECT object_key,ciphertext_size FROM attachment_versions WHERE user_id=? AND attachment_id=? AND source_revision=?').bind('u1','a1',1).first();assert.deepEqual(current,{object_key:'small-key',ciphertext_size:16,revision:2});assert.deepEqual(version,{object_key:'large-key',ciphertext_size:128})}finally{await mf.dispose()}});

