test('Worker inflight与待删新写入均绑定用户且完整备份导出复核revision和object_key',async()=>{const source=await readFile(new URL('../apps/worker/src/index.ts',import.meta.url),'utf8');assert.doesNotMatch(source,/INSERT INTO r2_inflight_uploads\(object_key,ciphertext_size,token,created_at\)/);assert.doesNotMatch(source,/INSERT INTO pending_r2_deletions\(object_key,ciphertext_size,created_at\)/);assert.match(source,/SELECT id,revision,object_key[\s\S]*FROM attachments WHERE user_id=\?/);assert.match(source,/backup_export_locks|backup_read_leases/)});

test('Worker Scheduled重叠执行仅一个持有数据库TTL租约',async()=>{const source=await readFile(new URL('../apps/worker/src/index.ts',import.meta.url),'utf8');assert.match(source,/INSERT INTO maintenance_leases[\s\S]*ON CONFLICT[\s\S]*expires_at<=\?/);assert.match(source,/DELETE FROM maintenance_leases WHERE name=\? AND token=\?/)});
